  const limit = Math.max(...nums);
  const isPrime = new Array(limit + 1).fill(true);
  isPrime[0] = false;
  isPrime[1] = false;
  for (let p = 2; p * p <= limit; p++) {
    if (!isPrime[p]) continue;
    for (let multiple = p * p; multiple <= limit; multiple += p) {
      isPrime[multiple] = false;
    }
  }
  const maxQueue = [];
  const minQueue = [];
  let maxHead = 0;
  let minHead = 0;
  let left = 0;
  let last = -1;
  let secondLast = -1;
  let count = 0;
  for (let right = 0; right < nums.length; right++) {
    if (isPrime[nums[right]]) {
      secondLast = last;
      last = right;
      while (maxQueue.length > maxHead && nums[maxQueue[maxQueue.length - 1]] <= nums[right]) {
        maxQueue.pop();
      }
      maxQueue.push(right);
      while (minQueue.length > minHead && nums[minQueue[minQueue.length - 1]] >= nums[right]) {
        minQueue.pop();
      }
      minQueue.push(right);
      while (nums[maxQueue[maxHead]] - nums[minQueue[minHead]] > k) {
        if (maxQueue[maxHead] < minQueue[minHead]) {
          left = maxQueue[maxHead] + 1;
          maxHead++;
        } else {
          left = minQueue[minHead] + 1;
          minHead++;
        }
      }
