function primeSubarray(nums, k) {
  // Try every subarray, tracking its prime count and its smallest and largest prime; primality by trial division.
  const isPrime = (value) => {
    if (value < 2) return false;
    for (let d = 2; d * d <= value; d++) if (value % d === 0) return false;
    return true;
  };
  let count = 0;
  for (let i = 0; i < nums.length; i++) {
    let primes = 0, low = Infinity, high = -Infinity;
    for (let j = i; j < nums.length; j++) {
      if (isPrime(nums[j])) {
        primes++;
        low = Math.min(low, nums[j]);
        high = Math.max(high, nums[j]);
      }
      if (primes >= 2 && high - low <= k) count++;
    }
  }
  return count;
}

