function generate(rand, size) {
  const small = size === 'small';
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const n = small ? 1 + Math.floor(rand() * 10) : 2000;
  // A low ceiling packs the array with small primes and repeats; the full range spreads the primes out.
  const top = small ? pick([5, 12, 30]) : pick([60, 1000, 50000]);
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  // k is drawn relative to the value range, so both tight and loose gaps occur at every scale.
  const k = Math.floor(rand() * (rand() < 0.5 ? top / 5 : top));
  return [nums, k];
}
